(function(){
if(!document.getElementById('acp-pcfg-range-css')){var st=document.createElement('style');st.id='acp-pcfg-range-css';st.textContent='.pcfg-range{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:12px;padding:10px 12px;background:var(--bg-secondary);border:1px solid var(--border);border-radius:8px}.pcfg-qbar{display:flex;gap:5px;flex-wrap:wrap}.pcfg-q{padding:5px 12px;background:var(--bg-card);border:1px solid var(--border);border-radius:5px;color:var(--text-secondary,#a0937e);font-size:12px;font-weight:600;cursor:pointer;font-family:inherit}.pcfg-q:hover{color:var(--accent-orange)}.pcfg-q.on{background:var(--accent-orange-dim);border-color:var(--accent-orange);color:var(--accent-orange)}.pcfg-dates{display:flex;align-items:center;gap:6px}.pcfg-range input[type=date]{padding:5px 8px;background:var(--bg-card);border:1px solid var(--border);border-radius:5px;color:var(--text-primary);font-size:12px;font-family:inherit;color-scheme:dark}.pcfg-range-sep{color:var(--text-secondary,#a0937e)}';document.head.appendChild(st);}
var BASE='https://xetg-lio4-hwsh.p7.xano.io/api:1LlCmuZl';
function authH(){return {Authorization:'Bearer '+(localStorage.getItem('xano_token')||'')};}
window.enrichPerfData=function(){
var el=document.getElementById('perf-data');if(!el)return;
var BENCH='SPY';
var STATE=window._perfState||(window._perfState={mode:'5y',from:'',to:''});
function fmt(m,v){if(v===null||v===undefined||isNaN(v))return{t:'—',c:'#6b5f50'};if(m==='vol')return{t:v.toFixed(1)+'%',c:v>30?'#e8524a':v>20?'#e8913a':'#6dd8a8'};if(m==='mdd')return{t:v.toFixed(1)+'%',c:'#e8524a'};if(m==='beta')return{t:v.toFixed(2),c:v>1.2?'#e8524a':v<0.8?'#3ec98c':'#e8d5b0'};return{t:(v>=0?'+':'')+v.toFixed(1)+'%',c:v>=0?'#3ec98c':'#e8524a'};}
function win(from,to){var o=window.oD||[];var w=[];for(var i=0;i<o.length;i++){var d=o[i].date;if((!from||d>=from)&&(!to||d<=to))w.push(o[i]);}return w;}
function metric(m,from,to){var w=win(from,to);if(w.length<2)return null;var L=w[w.length-1].close;if(!(L>0))return null;
if(m==='perf'){var s=w[0].close;return s>0?(L/s-1)*100:null;}
if(m==='cagr'){var s2=w[0].close,y=(new Date(w[w.length-1].date)-new Date(w[0].date))/(365.25*864e5);return s2>0&&y>0.05?(Math.pow(L/s2,1/y)-1)*100:null;}
if(m==='vol'){var r=[];for(var j=1;j<w.length;j++)if(w[j-1].close>0)r.push(Math.log(w[j].close/w[j-1].close));if(r.length<20)return null;var mu=r.reduce(function(p,q){return p+q},0)/r.length,v=0;for(var k=0;k<r.length;k++)v+=(r[k]-mu)*(r[k]-mu);return Math.sqrt(v/r.length)*Math.sqrt(252)*100;}
if(m==='mdd'){var pk=0,dd=0;for(var p=0;p<w.length;p++){var c=w[p].close;if(c>pk)pk=c;var x=pk>0?(pk-c)/pk:0;if(x>dd)dd=x;}return -dd*100;}
return null;}
function bcalc(o,bo,from,to){var bm={};for(var i=0;i<bo.length;i++)bm[bo[i].date]=bo[i].close;var P=[];for(i=0;i<o.length;i++){var d=o[i].date;if(from&&d<from)continue;if(to&&d>to)continue;var b=bm[d];if(!(b>0))continue;var s=o[i].close;if(!(s>0))continue;P.push([s,b]);}if(P.length<20)return null;var X=[],Y=[];for(i=1;i<P.length;i++){X.push(Math.log(P[i][0]/P[i-1][0]));Y.push(Math.log(P[i][1]/P[i-1][1]));}var n=X.length,mx=0,my=0;for(i=0;i<n;i++){mx+=X[i];my+=Y[i];}mx/=n;my/=n;var cv=0,vy=0;for(i=0;i<n;i++){cv+=(X[i]-mx)*(Y[i]-my);vy+=(Y[i]-my)*(Y[i]-my);}return vy>0?cv/vy:null;}
function lbench(tk,cb){window._bc=window._bc||{};if(window._bc[tk]!==undefined){cb(window._bc[tk]);return;}fetch(BASE+'/fmp/historical?ticker='+encodeURIComponent(tk),{headers:authH()}).then(function(r){return r.json();}).then(function(d){var a=(d&&d.historical&&d.historical.length)?d.historical.slice().reverse():null;window._bc[tk]=a;cb(a);}).catch(function(){window._bc[tk]=null;cb(null);});}
function bounds(){var o=window.oD||[];if(!o.length)return{from:'',to:''};var to=o[o.length-1].date,d=new Date(to),m=STATE.mode;
if(m==='max')return{from:o[0].date,to:to};
if(m==='1y')d.setFullYear(d.getFullYear()-1);else if(m==='3y')d.setFullYear(d.getFullYear()-3);else if(m==='5y')d.setFullYear(d.getFullYear()-5);
if(m==='custom')return{from:STATE.from,to:STATE.to};
return{from:d.toISOString().slice(0,10),to:to};}
var MET=[['perf','Performance'],['cagr','CAGR'],['vol','Volatilité ann.'],['mdd','Max Drawdown'],['beta','Beta vs S&P 500']];
function cell(lbl,f){return '<div class="pcfg"><div style="font-size:11px;color:var(--text-secondary,#a0937e);text-transform:uppercase;letter-spacing:.4px">'+lbl+'</div><div class="pcfg-v" style="color:'+f.c+'">'+f.t+'</div></div>';}
function draw(){var b=bounds();var o=window.oD;
var cells='';for(var i=0;i<4;i++){cells+=cell(MET[i][1],fmt(MET[i][0],(o&&o.length>=2)?metric(MET[i][0],b.from,b.to):null));}
cells+='<div class="pcfg" id="pcfg-beta"><div style="font-size:11px;color:var(--text-secondary,#a0937e);text-transform:uppercase;letter-spacing:.4px">Beta vs S&P 500</div><div class="pcfg-v" style="color:#6b5f50">...</div></div>';
var qb=[['1y','1A'],['3y','3A'],['5y','5A'],['max','Max']].map(function(x){return '<button class="pcfg-q'+(STATE.mode===x[0]?' on':'')+'" data-m="'+x[0]+'">'+x[1]+'</button>';}).join('');
var o2=window.oD||[],dmin=o2.length?o2[0].date:'',dmax=o2.length?o2[o2.length-1].date:'';
var bar='<div class="pcfg-range"><div class="pcfg-qbar">'+qb+'</div><div class="pcfg-dates"><input type="date" class="pcfg-d1" min="'+dmin+'" max="'+dmax+'" value="'+(STATE.mode==='custom'?STATE.from:'')+'"><span class="pcfg-range-sep">→</span><input type="date" class="pcfg-d2" min="'+dmin+'" max="'+dmax+'" value="'+(STATE.mode==='custom'?STATE.to:'')+'"></div></div>';
el.innerHTML=bar+'<div class="pcfg-grid">'+cells+'</div>';
if(o&&o.length>=2){lbench(BENCH,function(bo){var be=document.getElementById('pcfg-beta');if(!be)return;var f=fmt('beta',bo?bcalc(o,bo,b.from,b.to):null);var v=be.querySelector('.pcfg-v');v.textContent=f.t;v.style.color=f.c;});}
el.querySelectorAll('.pcfg-q').forEach(function(btn){btn.addEventListener('click',function(){STATE.mode=this.dataset.m;draw();});});
var d1=el.querySelector('.pcfg-d1'),d2=el.querySelector('.pcfg-d2');
function cust(){var a=d1&&d1.value,c=d2&&d2.value;if(a&&c&&a<=c){STATE.mode='custom';STATE.from=a;STATE.to=c;draw();}}
if(d1)d1.addEventListener('change',cust);if(d2)d2.addEventListener('change',cust);}
draw();};
})();